1	package com.example.starter.deicing.service;
2	
3	import com.example.starter.deicing.db.AllocationRepository;
4	import com.example.starter.deicing.db.BayRepository;
5	import com.example.starter.deicing.db.DeicingAllocationPo;
6	import com.example.starter.deicing.db.DeicingBayPo;
7	import com.example.starter.deicing.db.DeicingRequestPo;
8	import com.example.starter.deicing.db.LatchRepository;
9	import com.example.starter.deicing.db.RequestRepository;
10	import com.example.starter.deicing.db.TimetableRepository;
11	import com.example.starter.deicing.domain.DeicingType;
12	import com.example.starter.deicing.domain.RequestStatus;
13	import com.example.starter.deicing.web.ApiException;
14	import com.example.starter.deicing.web.dto.ApplicationRequest;
15	import com.example.starter.deicing.web.dto.BayTimelineView;
16	import com.example.starter.deicing.web.dto.MutationResponse;
17	import com.example.starter.deicing.web.dto.QueueItemView;
18	import com.example.starter.deicing.web.dto.SnapshotResponse;
19	import com.example.starter.deicing.web.dto.TakeoffResponse;
20	import com.example.starter.deicing.web.dto.TimelineResponse;
21	import java.time.Duration;
22	import java.time.Instant;
23	import java.util.ArrayList;
24	import java.util.Comparator;
25	import java.util.LinkedHashMap;
26	import java.util.List;
27	import java.util.Map;
28	import org.springframework.dao.DuplicateKeyException;
29	import org.springframework.stereotype.Service;
30	import org.springframework.transaction.annotation.Transactional;
31	
32	/**
33	 * 除冰排队核心服务：申请幂等、先申请先服务/截止优先出队、半开区间车位分配、
34	 * 两步法 HOT 判定与终态幂等。
35	 */
36	@Service
37	public class DeicingService {
38	
39	    private final RequestRepository requestRepository;
40	    private final AllocationRepository allocationRepository;
41	    private final BayRepository bayRepository;
42	    private final TimetableRepository timetableRepository;
43	    private final LatchRepository latchRepository;
44	    private final SchedulingCalculator calculator;
45	    private final ViewMapper viewMapper;
46	    private final TimeSource timeSource;
47	
48	    public DeicingService(RequestRepository requestRepository,
49	                          AllocationRepository allocationRepository,
50	                          BayRepository bayRepository,
51	                          TimetableRepository timetableRepository,
52	                          LatchRepository latchRepository,
53	                          SchedulingCalculator calculator,
54	                          ViewMapper viewMapper,
55	                          TimeSource timeSource) {
56	        this.requestRepository = requestRepository;
57	        this.allocationRepository = allocationRepository;
58	        this.bayRepository = bayRepository;
59	        this.timetableRepository = timetableRepository;
60	        this.latchRepository = latchRepository;
61	        this.calculator = calculator;
62	        this.viewMapper = viewMapper;
63	        this.timeSource = timeSource;
64	    }
65	
66	    /**
67	     * 除冰申请。requestId 幂等：同键同参返回首次结果，同键异参 409；
68	     * 同一航班仅允许一条进行中记录，并发申请由行锁 + 唯一约束唯一受理。
69	     */
70	    @Transactional
71	    public MutationResponse apply(ApplicationRequest request) {
72	        Instant now = timeSource.now();
73	        if (!request.targetTakeoffTime().isAfter(now)) {
74	            throw ApiException.badRequest("目标起飞时刻必须晚于当前时刻");
75	        }
76	        Instant requestDeadline = request.targetTakeoffTime()
77	                .minusSeconds(request.durationMinutes() * 60L);
78	        if (requestDeadline.isBefore(now)) {
79	            throw ApiException.badRequest("截止时刻（起飞时刻减除冰时长）已过");
80	        }
81	
82	        String fingerprint = Fingerprints.sha256(request.requestId(), request.flightNumber(),
83	                request.standCode(), request.type(), request.requiredBays(),
84	                request.durationMinutes(), request.targetTakeoffTime());
85	
86	        DeicingRequestPo existing = requestRepository.findByRequestId(request.requestId());
87	        if (existing != null) {
88	            return replayOrConflict(existing, fingerprint);
89	        }
90	
91	        Integer hotMinutes = resolveHot(request.type(), request.flightNumber());
92	
93	        try {
94	            // 航班闩锁串行化同一航班的并发申请
95	            latchRepository.lockFlight(request.flightNumber());
96	            existing = requestRepository.findByRequestId(request.requestId());
97	            if (existing != null) {
98	                return replayOrConflict(existing, fingerprint);
99	            }
100	            if (requestRepository.countActiveByFlight(request.flightNumber()) > 0) {
101	                throw ApiException.conflict("航班 " + request.flightNumber() + " 已存在进行中的除冰队列记录");
102	            }
103	            int activeBays = bayRepository.findActive().size();
104	            if (request.requiredBays() > activeBays) {
105	                throw ApiException.badRequest("所需车位数 " + request.requiredBays()
106	                        + " 超过可用车位数 " + activeBays);
107	            }
108	
109	            DeicingRequestPo po = new DeicingRequestPo();
110	            po.setRequestId(request.requestId());
111	            po.setFlightNumber(request.flightNumber());
112	            po.setStandCode(request.standCode());
113	            po.setType(request.type());
114	            po.setRequiredBays(request.requiredBays());
115	            po.setDurationMinutes(request.durationMinutes());
116	            po.setTargetTakeoffTime(request.targetTakeoffTime());
117	            po.setDeadline(request.targetTakeoffTime().minusSeconds(request.durationMinutes() * 60L));
118	            po.setStatus(RequestStatus.QUEUED);
119	            po.setHotMinutes(hotMinutes);
120	            po.setFingerprint(fingerprint);
121	            po.setCreatedAt(now);
122	            po.setUpdatedAt(now);
123	            requestRepository.insert(po);
124	            DeicingRequestPo stored = requestRepository.findByRequestId(request.requestId());
125	            return MutationResponse.of(viewMapper.toView(stored), false, List.of());
126	        } catch (DuplicateKeyException e) {
127	            DeicingRequestPo raced = requestRepository.findByRequestId(request.requestId());
128	            if (raced != null) {
129	                return replayOrConflict(raced, fingerprint);
130	            }
131	            throw e;
132	        }
133	    }
134	
135	    /**
136	     * 出队确认：仅队首（截止时刻最早、同刻按申请序号）可出队，禁止插队。
137	     * 排定成功返回车位与作业窗口；无法在截止前满足 HOT/时长时置 HOT_RISK，
138	     * 给出最早可重排时刻，不静默放行。
139	     */
140	    @Transactional
141	    public MutationResponse dequeue(String requestId) {
142	        DeicingRequestPo po = mustFind(requestId);
143	        if (po.getStatus() != RequestStatus.QUEUED && po.getStatus() != RequestStatus.HOT_RISK) {
144	            return mutationReplay(po);
145	        }
146	
147	        // 全局调度闩锁：所有出队分配串行化，杜绝并发双分配
148	        latchRepository.lockSchedule();
149	
150	        // QUEUED 与重排后待重新出队的 HOT_RISK 统一参与队首排序，禁止借重排插队
151	        List<DeicingRequestPo> queued = requestRepository.findAll().stream()
152	                .filter(r -> r.getStatus() == RequestStatus.QUEUED
153	                        || r.getStatus() == RequestStatus.HOT_RISK)
154	                .sorted(Comparator.comparing(DeicingRequestPo::getDeadline)
155	                        .thenComparingLong(DeicingRequestPo::getSeq))
156	                .toList();
157	        DeicingRequestPo head = queued.isEmpty() ? po : queued.get(0);
158	        if (!head.getRequestId().equals(requestId)) {
159	            throw ApiException.conflict("申请 " + requestId + " 不在队首，当前队首为 "
160	                    + head.getRequestId() + "，禁止插队");
161	        }
162	
163	        return schedule(head);
164	    }
165	
166	    private MutationResponse schedule(DeicingRequestPo po) {
167	        Instant now = timeSource.now();
168	        Duration duration = Duration.ofMinutes(po.getDurationMinutes());
169	        Instant deadline = po.getTargetTakeoffTime().minus(duration);
170	
171	        List<String> activeBays = bayRepository.findActive().stream()
172	                .map(DeicingBayPo::getBayCode).toList();
173	        List<DeicingAllocationPo> occupied = allocationRepository.findAll().stream()
174	                .filter(a -> a.getEndTime().isAfter(now)).toList();
175	
176	        // TWO_STEP：作业完成时刻须不早于 target-HOT，保证恰在 HOT 终点起飞仍有效
177	        Instant bandLower = now;
178	        if (po.getType() == DeicingType.TWO_STEP && po.getHotMinutes() != null) {
179	            Instant hotBound = po.getTargetTakeoffTime()
180	                    .minusSeconds(po.getHotMinutes() * 60L).minus(duration);
181	            if (hotBound.isAfter(bandLower)) {
182	                bandLower = hotBound;
183	            }
184	        }
185	
186	        BaySelection selection = selectBays(activeBays, bandLower, duration, occupied,
187	                po.getRequiredBays());
188	
189	        Instant now2 = timeSource.now();
190	        if (selection != null && !selection.start.isAfter(deadline)) {
191	            Instant start = selection.start;
192	            Instant end = start.plus(duration);
193	            // 数据库边界复核：半开 [start,end) 内部重叠才冲突，端点相接不冲突
194	            List<DeicingAllocationPo> clashes = allocationRepository.findOverlapping(
195	                    selection.bays, start, end);
196	            if (!clashes.isEmpty()) {
197	                throw ApiException.conflict("车位在 [" + start + ", " + end
198	                        + ") 已被占用，分配冲突");
199	            }
200	            for (String bay : selection.bays) {
201	                DeicingAllocationPo allocation = new DeicingAllocationPo();
202	                allocation.setRequestId(po.getRequestId());
203	                allocation.setFlightNumber(po.getFlightNumber());
204	                allocation.setBayCode(bay);
205	                allocation.setStartTime(start);
206	                allocation.setEndTime(end);
207	                allocation.setStatus(RequestStatus.SCHEDULED.name());
208	                allocation.setCreatedAt(now2);
209	                allocationRepository.insert(allocation);
210	            }
211	            po.setStatus(RequestStatus.SCHEDULED);
212	            po.setScheduledStart(start);
213	            po.setScheduledEnd(end);
214	            po.setHotRiskReason(null);
215	            po.setEarliestReassignTime(null);
216	            po.setUpdatedAt(now2);
217	            requestRepository.updateSchedule(po);
218	            DeicingRequestPo stored = requestRepository.findByRequestId(po.getRequestId());
219	            return MutationResponse.of(viewMapper.toView(stored), false, selection.bays);
220	        }
221	
222	        // 无法在截止前满足：置 HOT 风险，给出最早可重排（最早可重新开始作业）时刻
223	        BaySelection earliest = selectBays(activeBays, now, duration, occupied,
224	                po.getRequiredBays());
225	        Instant earliestStart = earliest == null ? now : earliest.start;
226	        HotRiskReason reason = earliestStart.plus(duration).isAfter(po.getTargetTakeoffTime())
227	                ? HotRiskReason.LATE_COMPLETION
228	                : HotRiskReason.HOT_EXPIRY_RISK;
229	        po.setStatus(RequestStatus.HOT_RISK);
230	        po.setHotRiskReason(reason.name());
231	        po.setEarliestReassignTime(earliestStart);
232	        po.setUpdatedAt(now2);
233	        requestRepository.updateSchedule(po);
234	        DeicingRequestPo stored = requestRepository.findByRequestId(po.getRequestId());
235	        return MutationResponse.of(viewMapper.toView(stored), false, List.of());
236	    }
237	
238	    /**
239	     * 作业开始：仅 SCHEDULED 可触发，开始后车位占用保留，不可被插队。
240	     */
241	    @Transactional
242	    public MutationResponse startJob(String requestId) {
243	        DeicingRequestPo po = mustFind(requestId);
244	        if (po.getStatus() == RequestStatus.SCHEDULED) {
245	            Instant now = timeSource.now();
246	            requestRepository.updateActualStart(requestId, RequestStatus.IN_PROGRESS, now, now);
247	            allocationRepository.updateStatusByRequest(requestId, RequestStatus.IN_PROGRESS.name());
248	            DeicingRequestPo stored = mustFind(requestId);
249	            List<String> bays = allocationRepository.findByRequestId(requestId).stream()
250	                    .map(DeicingAllocationPo::getBayCode).toList();
251	            return MutationResponse.of(viewMapper.toView(stored), false, bays);
252	        }
253	        if (po.getStatus() == RequestStatus.QUEUED || po.getStatus() == RequestStatus.HOT_RISK) {
254	            throw ApiException.conflict("申请 " + requestId + " 尚未完成出队排定，不能开始作业");
255	        }
256	        return mutationReplay(po);
257	    }
258	
259	    /**
260	     * 实际起飞回报。两步法：恰在 scheduledEnd+HOT 时刻起飞有效，晚于该时刻 HOT 失效，
261	     * 记录进入 HOT_EXPIRED 终态并要求重新除冰。已取消记录不会被复活。
262	     */
263	    @Transactional
264	    public TakeoffResponse reportTakeoff(String requestId, Instant actualTakeoffTime) {
265	        DeicingRequestPo po = mustFind(requestId);
266	
267	        if (po.getStatus() == RequestStatus.CANCELLED) {
268	            // 迟到起飞回报：幂等返回，已取消队列项不得复活
269	            return new TakeoffResponse(viewMapper.toView(po), false, true,
270	                    viewMapper.hotDeadline(po));
271	        }
272	        if (po.getStatus() == RequestStatus.TAKEN_OFF
273	                || po.getStatus() == RequestStatus.HOT_EXPIRED) {
274	            boolean valid = po.getStatus() == RequestStatus.TAKEN_OFF;
275	            return new TakeoffResponse(viewMapper.toView(po), valid, true,
276	                    viewMapper.hotDeadline(po));
277	        }
278	        if (po.getStatus() == RequestStatus.QUEUED || po.getStatus() == RequestStatus.HOT_RISK
279	                || po.getStatus() == RequestStatus.SCHEDULED) {
280	            throw ApiException.conflict("申请 " + requestId
281	                    + " 除冰作业尚未开始/处于 HOT 风险，不得放行起飞");
282	        }
283	        if (po.getScheduledEnd() == null || actualTakeoffTime.isBefore(po.getScheduledEnd())) {
284	            throw ApiException.badRequest("实际起飞时刻早于除冰完成时刻");
285	        }
286	
287	        boolean valid;
288	        RequestStatus nextStatus;
289	        if (po.getType() == DeicingType.TWO_STEP) {
290	            Instant hotDeadline = viewMapper.hotDeadline(po);
291	            // 半开 HOT 区间的对端取等号：恰在 HOT 终点起飞有效
292	            valid = !actualTakeoffTime.isAfter(hotDeadline);
293	            nextStatus = valid ? RequestStatus.TAKEN_OFF : RequestStatus.HOT_EXPIRED;
294	        } else {
295	            valid = true;
296	            nextStatus = RequestStatus.TAKEN_OFF;
297	        }
298	
299	        Instant now = timeSource.now();
300	        requestRepository.updateTakeoffResult(requestId, nextStatus, actualTakeoffTime, now);
301	        allocationRepository.updateStatusByRequest(requestId, nextStatus.name());
302	        DeicingRequestPo stored = mustFind(requestId);
303	        return new TakeoffResponse(viewMapper.toView(stored), valid, false,
304	                viewMapper.hotDeadline(stored));
305	    }
306	
307	    /**
308	     * 取消：释放车位占用，进入 CANCELLED 终态；终态记录上的重复取消幂等成功。
309	     */
310	    @Transactional
311	    public MutationResponse cancel(String requestId) {
312	        DeicingRequestPo po = mustFind(requestId);
313	        if (po.getStatus() == RequestStatus.CANCELLED) {
314	            return mutationReplay(po);
315	        }
316	        if (po.getStatus() == RequestStatus.TAKEN_OFF
317	                || po.getStatus() == RequestStatus.HOT_EXPIRED) {
318	            // 已进入其他终态，取消操作幂等返回但不改变终态
319	            return mutationReplay(po);
320	        }
321	        Instant now = timeSource.now();
322	        requestRepository.updateStatus(requestId, RequestStatus.CANCELLED, now);
323	        allocationRepository.deleteByRequest(requestId);
324	        return mutationReplay(mustFind(requestId));
325	    }
326	
327	    /**
328	     * HOT 风险航班重排起飞时刻：新时刻必须允许在最早可重排时刻之后完成作业，
329	     * 重排后回到排队态等待重新出队。
330	     */
331	    @Transactional
332	    public MutationResponse reschedule(String requestId, Instant newTargetTakeoffTime) {
333	        DeicingRequestPo po = mustFind(requestId);
334	        if (po.getStatus() != RequestStatus.HOT_RISK) {
335	            throw ApiException.conflict("仅 HOT_RISK 状态的记录可重排起飞时刻");
336	        }
337	        Instant now = timeSource.now();
338	        if (!newTargetTakeoffTime.isAfter(now)) {
339	            throw ApiException.badRequest("新起飞时刻必须晚于当前时刻");
340	        }
341	        Instant earliestStart = po.getEarliestReassignTime() == null ? now
342	                : po.getEarliestReassignTime();
343	        Instant earliestCompletion = earliestStart.plusSeconds(po.getDurationMinutes() * 60L);
344	        if (newTargetTakeoffTime.isBefore(earliestCompletion)) {
345	            throw ApiException.conflict("新起飞时刻早于最早可完成时刻 " + earliestCompletion);
346	        }
347	        Instant newDeadline = newTargetTakeoffTime.minusSeconds(po.getDurationMinutes() * 60L);
348	        requestRepository.updateReschedule(requestId, newTargetTakeoffTime, newDeadline, now);
349	        return mutationReplay(mustFind(requestId));
350	    }
351	
352	    /**
353	     * 队列快照：进行中记录在前（按截止时刻、申请序号），终态记录在后，重复查询稳定。
354	     */
355	    @Transactional(readOnly = true)
356	    public SnapshotResponse snapshot() {
357	        List<QueueItemView> items = requestRepository.findAll().stream()
358	                .sorted(snapshotOrder())
359	                .map(po -> viewMapper.toView(po))
360	                .toList();
361	        return new SnapshotResponse(timeSource.now(), items);
362	    }
363	
364	    /**
365	     * 车位占用时间线：按车位与占用起点排序，可复算、重复查询稳定。
366	     */
367	    @Transactional(readOnly = true)
368	    public TimelineResponse timeline() {
369	        Map<String, List<BayTimelineView.OccupancyView>> byBay = new LinkedHashMap<>();
370	        for (DeicingBayPo bay : bayRepository.findActive()) {
371	            byBay.put(bay.getBayCode(), new ArrayList<>());
372	        }
373	        for (DeicingAllocationPo allocation : allocationRepository.findAll()) {
374	            byBay.computeIfAbsent(allocation.getBayCode(), k -> new ArrayList<>())
375	                    .add(viewMapper.toOccupancy(allocation));
376	        }
377	        List<BayTimelineView> bays = byBay.entrySet().stream()
378	                .map(e -> new BayTimelineView(e.getKey(),
379	                        e.getValue().stream()
380	                                .sorted(Comparator.comparing(BayTimelineView.OccupancyView::start)
381	                                        .thenComparing(BayTimelineView.OccupancyView::requestId))
382	                                .toList()))
383	                .toList();
384	        return new TimelineResponse(timeSource.now(), bays);
385	    }
386	
387	    @Transactional(readOnly = true)
388	    public QueueItemView get(String requestId) {
389	        return viewMapper.toView(mustFind(requestId));
390	    }
391	
392	    // ---- 内部辅助 ----------------------------------------------------------
393	
394	    private Integer resolveHot(DeicingType type, String flightNumber) {
395	        if (type == DeicingType.ONE_STEP) {
396	            return null;
397	        }
398	        Integer hot = timetableRepository.findHotMinutes(flightNumber);
399	        if (hot == null || hot <= 0) {
400	            throw ApiException.badRequest("时刻表缺少航班 " + flightNumber
401	                    + " 的两步法防冰液保持时间（HOT）");
402	        }
403	        return hot;
404	    }
405	
406	    private MutationResponse replayOrConflict(DeicingRequestPo existing, String fingerprint) {
407	        if (!existing.getFingerprint().equals(fingerprint)) {
408	            throw ApiException.conflict("requestId " + existing.getRequestId()
409	                    + " 已存在但业务参数不一致，拒绝覆盖");
410	        }
411	        return mutationReplay(existing);
412	    }
413	
414	    private MutationResponse mutationReplay(DeicingRequestPo po) {
415	        List<String> bays = allocationRepository.findByRequestId(po.getRequestId()).stream()
416	                .map(DeicingAllocationPo::getBayCode).toList();
417	        return MutationResponse.of(viewMapper.toView(po), true, bays);
418	    }
419	
420	    private DeicingRequestPo mustFind(String requestId) {
421	        DeicingRequestPo po = requestRepository.findByRequestId(requestId);
422	        if (po == null) {
423	            throw ApiException.notFound("申请不存在: " + requestId);
424	        }
425	        return po;
426	    }
427	
428	    /**
429	     * 在 activeBays 中选择 requiredBays 个车位，使作业能在 earliest 之后最早开始；
430	     * 起点并列时优先共同空闲更久、车位编号更小的组合，保证结果确定。
431	     */
432	    private BaySelection selectBays(List<String> activeBays, Instant earliest, Duration duration,
433	                                    List<DeicingAllocationPo> occupied, int requiredBays) {
434	        record Candidate(String bay, Instant start, Instant end) {
435	        }
436	        Map<String, List<SchedulingCalculator.BayWindow>> windows = new LinkedHashMap<>();
437	        for (String bay : activeBays) {
438	            windows.put(bay, calculator.freeWindows(bay, earliest, duration, occupied));
439	        }
440	
441	        List<Instant> starts = windows.values().stream().flatMap(List::stream)
442	                .map(SchedulingCalculator.BayWindow::windowStart)
443	                .distinct().sorted().toList();
444	
445	        for (Instant start : starts) {
446	            List<Candidate> covering = new ArrayList<>();
447	            for (Map.Entry<String, List<SchedulingCalculator.BayWindow>> entry : windows.entrySet()) {
448	                SchedulingCalculator.BayWindow window = entry.getValue().stream()
449	                        .filter(w -> !start.isBefore(w.windowStart())
450	                                && !start.plus(duration).isAfter(w.windowEnd()))
451	                        .findFirst().orElse(null);
452	                if (window != null) {
453	                    covering.add(new Candidate(entry.getKey(), start, window.windowEnd()));
454	                }
455	            }
456	            if (covering.size() >= requiredBays) {
457	                covering.sort(Comparator.comparing(Candidate::end).reversed()
458	                        .thenComparing(Candidate::bay));
459	                List<String> chosen = covering.subList(0, requiredBays).stream()
460	                        .map(Candidate::bay).sorted().toList();
461	                return new BaySelection(start, chosen);
462	            }
463	        }
464	        return null;
465	    }
466	
467	    private static Comparator<DeicingRequestPo> snapshotOrder() {
468	        return Comparator.comparingInt((DeicingRequestPo po) -> statusGroup(po.getStatus()))
469	                .thenComparing(DeicingRequestPo::getDeadline)
470	                .thenComparingLong(DeicingRequestPo::getSeq);
471	    }
472	
473	    private static int statusGroup(RequestStatus status) {
474	        return switch (status) {
475	            case QUEUED, SCHEDULED, IN_PROGRESS, HOT_RISK -> 0;
476	            case TAKEN_OFF, HOT_EXPIRED, CANCELLED -> 1;
477	        };
478	    }
479	
480	    private record BaySelection(Instant start, List<String> bays) {
481	    }
482	}
