13	
14	/**
15	 * 除冰排队记录数据访问。
16	 */
17	@Repository
18	public class RequestRepository {
19	
20	    private static final String COLUMNS = """
21	            id, request_id, flight_number, stand_code, deicing_type, required_bays,
22	            duration_minutes, target_takeoff_time, deadline, status, scheduled_start,
23	            scheduled_end, actual_start, hot_minutes, hot_risk_reason,
24	            earliest_reassign_time, actual_takeoff_time, fingerprint, created_at, updated_at
25	            """;
26	
27	    private final JdbcTemplate jdbcTemplate;
28	
29	    public RequestRepository(JdbcTemplate jdbcTemplate) {
30	        this.jdbcTemplate = jdbcTemplate;
31	    }
32	
33	    private static final RowMapper<DeicingRequestPo> MAPPER = (ResultSet rs, int rowNum) -> map(rs);
34	
35	    static DeicingRequestPo map(ResultSet rs) throws SQLException {
36	        DeicingRequestPo po = new DeicingRequestPo();
37	        po.setId(rs.getLong("id"));
38	        po.setRequestId(rs.getString("request_id"));
39	        po.setSeq(rs.getLong("id"));
40	        po.setFlightNumber(rs.getString("flight_number"));
41	        po.setStandCode(rs.getString("stand_code"));
42	        po.setType(DeicingType.valueOf(rs.getString("deicing_type")));
43	        po.setRequiredBays(rs.getInt("required_bays"));
44	        po.setDurationMinutes(rs.getInt("duration_minutes"));
45	        po.setTargetTakeoffTime(RowMappers.instant(rs, "target_takeoff_time"));
46	        po.setDeadline(RowMappers.instant(rs, "deadline"));
47	        po.setStatus(RequestStatus.valueOf(rs.getString("status")));
48	        po.setScheduledStart(RowMappers.instant(rs, "scheduled_start"));
49	        po.setScheduledEnd(RowMappers.instant(rs, "scheduled_end"));
50	        po.setActualStart(RowMappers.instant(rs, "actual_start"));
51	        int hot = rs.getInt("hot_minutes");
52	        po.setHotMinutes(rs.wasNull() ? null : hot);
53	        po.setHotRiskReason(rs.getString("hot_risk_reason"));
54	        po.setEarliestReassignTime(RowMappers.instant(rs, "earliest_reassign_time"));
55	        po.setActualTakeoffTime(RowMappers.instant(rs, "actual_takeoff_time"));
56	        po.setFingerprint(rs.getString("fingerprint"));
57	        po.setCreatedAt(RowMappers.instant(rs, "created_at"));
58	        po.setUpdatedAt(RowMappers.instant(rs, "updated_at"));
59	        return po;
60	    }
61	
62	    /**
63	     * 插入排队记录，申请序号取自增主键。
64	     */
65	    public void insert(DeicingRequestPo po) {
66	        jdbcTemplate.update("""
67	                        INSERT INTO deicing_request (
68	                            request_id, flight_number, stand_code, deicing_type, required_bays,
69	                            duration_minutes, target_takeoff_time, deadline, status,
70	                            hot_minutes, fingerprint, created_at, updated_at
71	                        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
72	                        """,
73	                po.getRequestId(), po.getFlightNumber(), po.getStandCode(), po.getType().name(),
74	                po.getRequiredBays(), po.getDurationMinutes(),
75	                Timestamp.from(po.getTargetTakeoffTime()), Timestamp.from(po.getDeadline()),
76	                po.getStatus().name(), po.getHotMinutes(), po.getFingerprint(),
77	                Timestamp.from(po.getCreatedAt()), Timestamp.from(po.getUpdatedAt()));
78	    }
79	
80	    public DeicingRequestPo findByRequestId(String requestId) {
81	        List<DeicingRequestPo> list = jdbcTemplate.query(
82	                "SELECT " + COLUMNS + " FROM deicing_request WHERE request_id = ?", MAPPER, requestId);
83	        return list.isEmpty() ? null : list.get(0);
84	    }
85	
86	    public List<DeicingRequestPo> findAll() {
87	        return jdbcTemplate.query("SELECT " + COLUMNS + " FROM deicing_request ORDER BY id", MAPPER);
88	    }
89	
90	    /**
91	     * 统计航班未终结（排队/已排定/作业中/HOT 风险）的记录数。
92	     */
93	    public int countActiveByFlight(String flightNumber) {
94	        Integer count = jdbcTemplate.queryForObject("""
95	                        SELECT COUNT(*) FROM deicing_request
96	                        WHERE flight_number = ?
97	                          AND status IN ('QUEUED', 'SCHEDULED', 'IN_PROGRESS', 'HOT_RISK')
98	                        """,
99	                Integer.class, flightNumber);
100	        return count == null ? 0 : count;
101	    }
102	
103	    /**
104	     * 排定结果落库：状态、作业窗口与 HOT 风险信息。
105	     */
106	    public void updateSchedule(DeicingRequestPo po) {
107	        jdbcTemplate.update("""
108	                        UPDATE deicing_request SET
109	                            status = ?, scheduled_start = ?, scheduled_end = ?,
110	                            hot_risk_reason = ?, earliest_reassign_time = ?, updated_at = ?
111	                        WHERE request_id = ?
112	                        """,
113	                po.getStatus().name(), ts(po.getScheduledStart()), ts(po.getScheduledEnd()),
114	                po.getHotRiskReason(), ts(po.getEarliestReassignTime()),
115	                ts(po.getUpdatedAt()), po.getRequestId());
116	    }
117	
118	    public void updateActualStart(String requestId, RequestStatus status, Instant actualStart,
119	                                  Instant updatedAt) {
120	        jdbcTemplate.update("""
121	                        UPDATE deicing_request SET status = ?, actual_start = ?, updated_at = ?
122	                        WHERE request_id = ?
123	                        """,
124	                status.name(), Timestamp.from(actualStart), Timestamp.from(updatedAt), requestId);
125	    }
126	
127	    public void updateTakeoffResult(String requestId, RequestStatus status, Instant actualTakeoffTime,
128	                                    Instant updatedAt) {
129	        jdbcTemplate.update("""
130	                        UPDATE deicing_request SET status = ?, actual_takeoff_time = ?, updated_at = ?
131	                        WHERE request_id = ?
132	                        """,
133	                status.name(), Timestamp.from(actualTakeoffTime), Timestamp.from(updatedAt), requestId);
134	    }
135	
136	    public void updateStatus(String requestId, RequestStatus status, Instant updatedAt) {
137	        jdbcTemplate.update(
138	                "UPDATE deicing_request SET status = ?, updated_at = ? WHERE request_id = ?",
139	                status.name(), Timestamp.from(updatedAt), requestId);
140	    }
141	
142	    /**
143	     * HOT 风险航班重排：更新目标起飞时刻并回到排队态，清除旧排定与风险标记。
144	     */
145	    public void updateReschedule(String requestId, Instant newTargetTakeoffTime, Instant newDeadline,
146	                                 Instant updatedAt) {
147	        jdbcTemplate.update("""
148	                        UPDATE deicing_request SET
149	                            target_takeoff_time = ?, deadline = ?, status = 'QUEUED',
150	                            scheduled_start = NULL, scheduled_end = NULL,
151	                            hot_risk_reason = NULL, earliest_reassign_time = NULL,
152	                            updated_at = ?
153	                        WHERE request_id = ?
154	                        """,
155	                Timestamp.from(newTargetTakeoffTime), Timestamp.from(newDeadline),
156	                Timestamp.from(updatedAt), requestId);
157	    }
158	
159	    private static Timestamp ts(Instant instant) {
160	        return instant == null ? null : Timestamp.from(instant);
161	    }
162	}
