57	    @Test
58	    void concurrentApplicationsForSameFlightOnlyOneAccepted() throws Exception {
59	        int threads = 4;
60	        ExecutorService pool = Executors.newFixedThreadPool(threads);
61	        CountDownLatch ready = new CountDownLatch(threads);
62	        CountDownLatch fire = new CountDownLatch(1);
63	        Map<Integer, String> outcomes = new ConcurrentHashMap<>();
64	
65	        List<Future<?>> futures = new ArrayList<>();
66	        for (int i = 0; i < threads; i++) {
67	            final int index = i;
68	            futures.add(pool.submit(() -> {
69	                ready.countDown();
70	                fire.await(10, TimeUnit.SECONDS);
71	                try {
72	                    MutationResponse response = service.apply(oneStep("REQ-F" + index, "CA101"));
73	                    outcomes.put(index, "ACCEPTED:" + response.item().status());
74	                } catch (ApiException e) {
75	                    outcomes.put(index, "REJECTED:" + e.getStatus().name());
76	                }
77	                return null;
78	            }));
79	        }
80	
81	        assertThat(ready.await(10, TimeUnit.SECONDS)).isTrue();
82	        fire.countDown();
83	        for (Future<?> future : futures) {
84	            future.get(30, TimeUnit.SECONDS);
85	        }
86	        pool.shutdown();
87	        assertThat(pool.awaitTermination(10, TimeUnit.SECONDS)).isTrue();
88	
89	        long accepted = outcomes.values().stream().filter(v -> v.startsWith("ACCEPTED")).count();
90	        long rejected = outcomes.values().stream().filter(v -> v.startsWith("REJECTED")).count();
91	        assertThat(accepted).as("恰好一个并发申请被受理").isEqualTo(1);
92	        assertThat(rejected).isEqualTo(threads - 1);
93	
94	        Integer activeCount = jdbcTemplate.queryForObject("""
95	                        SELECT COUNT(*) FROM deicing_request
96	                        WHERE flight_number = 'CA101'
97	                          AND status IN ('QUEUED', 'SCHEDULED', 'IN_PROGRESS', 'HOT_RISK')
98	                        """,
99	                Integer.class);
100	        assertThat(activeCount).isEqualTo(1);
101	    }
