103	    @Test
104	    void concurrentSameKeyApplicationsYieldSingleRecord() throws Exception {
105	        int threads = 4;
106	        ExecutorService pool = Executors.newFixedThreadPool(threads);
107	        CountDownLatch ready = new CountDownLatch(threads);
108	        CountDownLatch fire = new CountDownLatch(1);
109	        Map<Integer, String> outcomes = new ConcurrentHashMap<>();
110	
111	        List<Future<?>> futures = new ArrayList<>();
112	        for (int i = 0; i < threads; i++) {
113	            final int index = i;
114	            futures.add(pool.submit(() -> {
115	                ready.countDown();
116	                fire.await(10, TimeUnit.SECONDS);
117	                MutationResponse response = service.apply(oneStep("REQ-SAME", "CA202"));
118	                outcomes.put(index, response.item().status() + ":" + response.item().sequence());
119	                return null;
120	            }));
121	        }
122	
123	        assertThat(ready.await(10, TimeUnit.SECONDS)).isTrue();
124	        fire.countDown();
125	        for (Future<?> future : futures) {
126	            future.get(30, TimeUnit.SECONDS);
127	        }
128	        pool.shutdown();
129	        assertThat(pool.awaitTermination(10, TimeUnit.SECONDS)).isTrue();
130	
131	        assertThat(outcomes.values()).as("所有并发同键请求看到同一条记录")
132	                .hasSize(threads).containsOnly("QUEUED:" + outcomes.values().iterator().next()
133	                        .substring("QUEUED:".length()));
134	        Integer count = jdbcTemplate.queryForObject(
135	                "SELECT COUNT(*) FROM deicing_request WHERE request_id = 'REQ-SAME'",
136	                Integer.class);
137	        assertThat(count).isEqualTo(1);
138	    }
