140	    @Test
141	    void concurrentDequeueNeverCreatesOverlappingAllocations() throws Exception {
142	        // 4 个不同航班，各需全部 4 个车位、截止时刻相同 → 按申请序号串行出队
143	        String[] flights = {"CA101", "CA202", "MU510", "CZ303"};
144	        for (int i = 0; i < flights.length; i++) {
145	            ApplicationRequest request = new ApplicationRequest(
146	                    "REQ-D" + i, flights[i], "STAND-" + flights[i],
147	                    DeicingType.ONE_STEP, 4, 20, T0.plus(Duration.ofMinutes(180)));
148	            service.apply(request);
149	        }
150	
151	        int threads = flights.length;
152	        ExecutorService pool = Executors.newFixedThreadPool(threads);
153	
154	        // 多轮并发竞争出队，直到 4 个航班全部排定（非队首的并发尝试返回 409）
155	        Instant deadline = Instant.now().plusSeconds(60);
156	        while (Instant.now().isBefore(deadline)) {
157	            List<String> queuedIds = jdbcTemplate.queryForList(
158	                    "SELECT request_id FROM deicing_request WHERE status = 'QUEUED'",
159	                    String.class);
160	            if (queuedIds.isEmpty()) {
161	                break;
162	            }
163	            CountDownLatch ready = new CountDownLatch(queuedIds.size());
164	            CountDownLatch fire = new CountDownLatch(1);
165	            List<Future<?>> round = new ArrayList<>();
166	            for (String requestId : queuedIds) {
167	                round.add(pool.submit(() -> {
168	                    ready.countDown();
169	                    fire.await(10, TimeUnit.SECONDS);
170	                    try {
171	                        service.dequeue(requestId);
172	                    } catch (ApiException ignored) {
