            quantity = reservation.getQuantityLiters();
            reservationRepository.transitionActive(po.getRequestId(), SETTLED, now);
        } else {
            quantity = rate(TWO_STEP) * durationMinutes;
        }
        deductAndRecord(po.getRequestId(), FLUID_TWO_STEP, quantity, minutes, now);
    } else {
        int minutes = actual minutes: 
        Instant start = po.getActualStart() != null ? po.getActualStart() : po.getScheduledStart();
        long secs = Duration.between(start, actualTakeoffTime).getSeconds();
        int minutes = (int) Math.max(1, (secs + 59) / 60);
        quantity = rate(ONE_STEP) * minutes;
        deductAndRecord(...FLUID_ONE_STEP...);
    }
}

private void deductAndRecord(requestId, fluidCode, quantity, minutes, now) {
    fluidRepository.lockFluid(fluidCode);
    deductFefo(fluidCode, quantity, now);
    fluidRepository.insertConsumption(requestId, fluidCode, quantity, minutes, now);
}

private void deductFefo(String fluidCode, BigDecimal quantity, Instant now) {
    BigDecimal remaining = quantity;
    for (batch : fluidRepository.lockUsableBatchesFefo(fluidCode, now)) {
        if (remaining <= 0) break;
        BigDecimal take = min(batch.remaining, remaining);
        updateBatchRemaining(batch.id, batch.remaining - take);
        remaining -= take;
    }
    if (remaining > 0) {
        FluidBatchPo last = fluidRepository.lockLatestExpiryBatch(fluidCode);
        // 断供透支：最后批次剩余量转负，台账保持可复算
        updateBatchRemaining(last.id, last.remaining - remaining);
    }
}
